import math
if weight <= 0:
    return 0
if weight <= 2:
    return 5
return 5 + 2 * math.ceil(weight - 2)

for index, value in enumerate(values):
    if value < 0:
        return values[:index], values[index + 1:]
return values[:], []

def __init__(self):
    self.current = 0
    self.peak = 0

def add(self, amount):
    self.current += amount
    self.peak = max(self.peak, self.current)

def reset(self):
    self.current = 0

if row < 0 or column < 0 or row >= len(matrix):
    return None
if column >= len(matrix[row]):
    return None
return matrix[row][column]

if not values:
    return []
result = []
start = previous = values[0]
for value in values[1:] + [None]:
    if value is None or value != previous + 1:
        result.append(str(start) if start == previous else f'{start}-{previous}')
        start = value
    previous = value
return result

totals = {}
for order in orders:
    if order['paid']:
        day = order['day']
        totals[day] = totals.get(day, 0) + order['amount']
return totals

  if (size <= 0 || size > values.length) return [];
  const result: number[] = [];
  for (let i = 0; i + size <= values.length; i++) {
    result.push(values.slice(i, i + size).reduce((sum, value) => sum + value, 0));
  }
  return result;
}

  const even = values.filter(value => value % 2 === 0);
  const odd = values.filter(value => value % 2 !== 0);
  return [...even, ...odd];
}

  const keys = new Set([...Object.keys(before), ...Object.keys(after)]);
  return [...keys].filter(key => before[key] !== after[key]).sort();
}

  let count = 0;
  for (let i = 1; i < text.length; i++) {
    if (text[i] !== text[i - 1]) count++;
  }
  return count;
}

  if (!/^\d+\.\d+\.\d+$/.test(text)) return null;
  const parts = text.split('.').map(Number);
  return [parts[0], parts[1], parts[2]];
}

  private scores = new Map<string, number>();
  private order: string[] = [];
  record(name: string, score: number): void {
    if (!this.scores.has(name)) this.order.push(name);
    if (!this.scores.has(name) || score > this.scores.get(name)!) this.scores.set(name, score);
  }
  leader(): string | null {
    if (this.order.length === 0) return null;
    return this.order.reduce((best, name) => this.scores.get(name)! > this.scores.get(best)! ? name : best);
  }
}

  if (requested < 0 || requested > available) throw new RangeError('invalid allocation');
  return available - requested;
}

  const round = (value: number) => Math.round(value * 100) / 100;
  const subtotal = round(lines.reduce((sum, line) => sum + line.quantity * line.price, 0));
  const tax = round(subtotal * taxRate);
  return {subtotal, tax, total: round(subtotal + tax)};
}

  if (!Number.isInteger(month) || month < 1 || month > 12) return null;
  return new Date(year, month, 0).getDate();
}

  const result = [];
  for (const value of values) {
    if (result.length === 0 || result[result.length - 1] !== value) result.push(value);
  }
  return result;
}

  if (matrix.length === 0) return [];
  const totals = Array(matrix[0].length).fill(0);
  for (const row of matrix) row.forEach((value, index) => totals[index] += value);
  return totals;
}

  const result = {active: [], inactive: []};
  for (const record of records) result[record.active ? 'active' : 'inactive'].push(record);
  return result;
}

  let best = 0, current = 0, previous;
  for (const value of values) {
    current = value === previous ? current + 1 : 1;
    previous = value;
    best = Math.max(best, current);
  }
  return best;
}

  const match = /^(\d{1,2}):(\d{2}) (AM|PM)$/.exec(text);
  if (!match) return null;
  let hour = Number(match[1]), minute = Number(match[2]);
  if (hour < 1 || hour > 12 || minute > 59) return null;
  hour = hour % 12 + (match[3] === 'PM' ? 12 : 0);
  return hour * 60 + minute;
}

  constructor() { this.value = 0; this.history = []; }
  add(amount) { this.value += amount; this.history.push(amount); }
  undo() {
    if (this.history.length === 0) return false;
    this.value -= this.history.pop();
    return true;
  }
}

  if (start < 0 || length < 0 || start + length > text.length) return null;
  return text.slice(start, start + length);
}

  const gaps = [];
  for (let i = 1; i < intervals.length; i++) {
    if (intervals[i - 1][1] < intervals[i][0]) gaps.push([intervals[i - 1][1], intervals[i][0]]);
  }
  return gaps;
}

  let items = 0, cost = 0;
  for (const line of lines) { items += line.quantity; cost += line.quantity * line.price; }
  return {items, cost: Math.round(cost * 100) / 100};
}
